DECLARE n NUMBER; BEGIN SELECT COUNT(*) INTO n FROM user_tables WHERE table_name='CPF_XA_RECOVERY'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE cpf_xa_recovery (transaction_id VARCHAR2(80) PRIMARY KEY, attempt_id VARCHAR2(120) NOT NULL, outcome VARCHAR2(30) NOT NULL, fencing_token NUMBER(19) DEFAULT 0 NOT NULL, detail VARCHAR2(1000), updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP NOT NULL)'; EXECUTE IMMEDIATE 'CREATE INDEX ix_cpf_xa_recovery_outcome ON cpf_xa_recovery(outcome,updated_at)'; END IF; END;
/
DECLARE n NUMBER; BEGIN SELECT COUNT(*) INTO n FROM user_tables WHERE table_name='CPF_TAMPER_AUDIT_HEAD'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE cpf_tamper_audit_head (head_id NUMBER(10) PRIMARY KEY, sequence_no NUMBER(19) NOT NULL, current_hash VARCHAR2(64) NOT NULL, version_no NUMBER(19) DEFAULT 0 NOT NULL, updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT ck_cpf_tamper_audit_head_id CHECK(head_id=1))'; END IF; END;
/
MERGE INTO cpf_tamper_audit_head h USING (SELECT 1 head_id FROM dual) s ON(h.head_id=s.head_id) WHEN NOT MATCHED THEN INSERT(head_id,sequence_no,current_hash,version_no) VALUES(1,0,'GENESIS',0);
DECLARE n NUMBER; BEGIN SELECT COUNT(*) INTO n FROM user_tables WHERE table_name='CPF_TAMPER_AUDIT'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE cpf_tamper_audit (sequence_no NUMBER(19) PRIMARY KEY, transaction_id VARCHAR2(80) NOT NULL, actor_id VARCHAR2(160), action_code VARCHAR2(160) NOT NULL, payload_hash VARCHAR2(64) NOT NULL, previous_hash VARCHAR2(64) NOT NULL, current_hash VARCHAR2(64) NOT NULL, key_id VARCHAR2(200) NOT NULL, key_version VARCHAR2(100), algorithm VARCHAR2(100) NOT NULL, certificate_id VARCHAR2(200), signature_value BLOB NOT NULL, occurred_at TIMESTAMP(3) NOT NULL)'; EXECUTE IMMEDIATE 'CREATE UNIQUE INDEX uk_cpf_tamper_audit_current_hash ON cpf_tamper_audit(current_hash)'; EXECUTE IMMEDIATE 'CREATE INDEX ix_cpf_tamper_audit_tx ON cpf_tamper_audit(transaction_id,sequence_no)'; END IF; END;
/

DECLARE n NUMBER; BEGIN SELECT COUNT(*) INTO n FROM user_tables WHERE table_name='CPF_REF_TCC_RESERVATION'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE cpf_ref_tcc_reservation (transaction_id VARCHAR2(80) NOT NULL, branch_id VARCHAR2(120) NOT NULL, idempotency_key VARCHAR2(160) NOT NULL, account_id VARCHAR2(160) NOT NULL, amount NUMBER(38,8) NOT NULL, state VARCHAR2(30) NOT NULL, deadline_at TIMESTAMP(3) NOT NULL, fencing_token NUMBER(19) DEFAULT 0 NOT NULL, review_reason VARCHAR2(500), updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT pk_cpf_ref_tcc PRIMARY KEY(transaction_id,branch_id), CONSTRAINT uk_cpf_ref_tcc_idem UNIQUE(idempotency_key))'; EXECUTE IMMEDIATE 'CREATE INDEX ix_cpf_ref_tcc_recovery ON cpf_ref_tcc_reservation(state,deadline_at,updated_at)'; END IF; END;
/
